#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <cuda_bf16.h>
#include <stdint.h>

static __device__ __forceinline__ float sigmoid_silu(float x) {
    return x / (1.0f + __expf(-x));
}

static __device__ __forceinline__ float bf16bits_to_float(uint16_t h) {
    union { uint32_t u; float f; } v;
    v.u = ((uint32_t)h) << 16;
    return v.f;
