static __device__ __forceinline__ uint16_t float_to_bf16bits(float f) {
    union { float f; uint32_t u; } v;
    v.f = f;
    uint32_t lsb = (v.u >> 16) & 1u;
    uint32_t bias = 0x7fffu + lsb;
    return (uint16_t)((v.u + bias) >> 16);
}

__global__ __launch_bounds__(256)
void swiglu_bf16_pair_kernel(const uint32_t* __restrict__ a,
                             const uint32_t* __restrict__ b,
                             uint32_t* __restrict__ c,
                             int64_t n_pairs) {
    int64_t i = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    int64_t stride = (int64_t)blockDim.x * gridDim.x;
    for (; i < n_pairs; i += stride) {
        uint32_t av = a[i];
        uint32_t bv = b[i];
        uint16_t a0 = (uint16_t)(av & 0xffffu);
        uint16_t a1 = (uint16_t)(av >> 16);
        uint16_t b0 = (uint16_t)(bv & 0xffffu);
        uint16_t b1 = (uint16_t)(bv >> 16);
        float af0 = bf16bits_to_float(a0);
        float af1 = bf16bits_to_float(a1);
        float bf0 = bf16bits_to_float(b0);
        float bf1 = bf16bits_to_float(b1);
        float s0 = bf16bits_to_float(float_to_bf16bits(sigmoid_silu(af0)));
        float s1 = bf16bits_to_float(float_to_bf16bits(sigmoid_silu(af1)));
        uint16_t c0 = float_to_bf16bits(s0 * bf0);
        uint16_t c1 = float_to_bf16bits(s1 * bf1);
        c[i] = ((uint32_t)c1 << 16) | (uint32_t)c0;
    }
}

__global__ __launch_bounds__(256)
void swiglu_bf16_tail_kernel(const uint16_t* __restrict__ a,
                             const uint16_t* __restrict__ b,
                             uint16_t* __restrict__ c,
                             int64_t idx) {
    float af = bf16bits_to_float(a[idx]);
    float bf = bf16bits_to_float(b[idx]);
    float s = bf16bits_to_float(float_to_bf16bits(sigmoid_silu(af)));
    c[idx] = float_to_bf16bits(s * bf);
