        float bf0 = __half2float(bh0);
        float bf1 = __half2float(bh1);
        float s0 = __half2float(__float2half_rn(sigmoid_silu(af0)));
        float s1 = __half2float(__float2half_rn(sigmoid_silu(af1)));
        uint16_t c0 = __half_as_ushort(__float2half_rn(s0 * bf0));
        uint16_t c1 = __half_as_ushort(__float2half_rn(s1 * bf1));
