    int64_t i = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    int64_t inc = (int64_t)blockDim.x * gridDim.x;
    for (; i < total; i += inc) {
        int64_t r = i / D;
        int64_t col = i - r * D;
        int64_t off = r * row_stride + col;
        float af = bf16bits_to_float(a[off]);
        float bf = bf16bits_to_float(b[off]);
        float s = bf16bits_to_float(float_to_bf16bits(sigmoid_silu(af)));
        c[off] = float_to_bf16bits(s * bf);
